static void Main(string[] args)
{
    int a = 10, b = 20;
    Console.Write("Result before swap: " + a + " " + b + ", ");
    swap(ref a, ref b);
}
static void swap(ref int i, ref int j)
{
    int t = i;
    i = j;
    j = t;
    Console.Write("Result after swap: " + i + " " + j);
}

